let inc = 3;

function setup() {
  createCanvas(500, 500);
}

function draw() {
  background(0);
  translate(width/2, height/2);

  for (let i = 3.; i <= 48; i += (Math.max(0.001, Math.abs(3.)) || 1)) {
    let speed = frameCount / i * 0.25;
    push();
    rotate(speed);
    for (let f = 0; f < i; f++) {
      let theta = f / i * TWO_PI;
      ellipse(cos(theta) * i * 5, sin(theta) * i * 5, 10, 10);
    }
    pop();
  }
}
